mapper.select:
SELECT question AS keyword, COUNT(*) AS freq FROM question_log WHERE question IS NOT NULL AND question <> '' AND (source IS NULL OR source <> 'rejected') AND CHAR_LENGTH(question) > 1 AND question NOT REGEXP '^[0-9]+$'
AND DATE(created_at) >= #{startDate}
AND DATE(created_at) <= #{endDate}
GROUP BY question ORDER BY freq DESC LIMIT #{limit}
